style.css:
html {
background: #000000 !important;
}

body {
background-color: #07040a !important;
background-image:
radial-gradient(
circle at 50% 50%,
rgba(75, 25, 105, 0.22),
transparent 55%
) !important;
box-shadow:
inset 0 0 160px rgba(0, 0, 0, 0.95) !important;
}

/* Ombres discrètes, sans modifier la mise en page */
body::before {
content: "" !important;
position: fixed !important;
inset: 0 !important;
z-index: 0 !important;
pointer-events: none !important;
background:
linear-gradient(
90deg,
rgba(0, 0, 0, 0.85),
transparent 22%,
transparent 78%,
rgba(0, 0, 0, 0.85)
) !important;
}

/* Le contenu reste au-dessus de l’ombre */
body > * {
position: relative;
z-index: 1;
}
